16	import { useForm } from '@mantine/form';
17	import { IconX } from '@tabler/icons-react';
18	import { zod4Resolver } from 'mantine-form-zod-resolver';
19	import { useRouter } from 'next/navigation';
20	import { useState } from 'react';
21	import z from 'zod';
22	
23	import { PasswordFields } from '@/components/PasswordFields/PasswordFields';
24	import {
25	    authClient,
26	    signInWithGoogle,
27	    signInWithMicrosoft,
28	} from '@/lib/auth.client';
29	import { config } from '@/lib/config';
30	import { captureUnexpectedError } from '@/lib/observability/sentry';
31	import { getPublicBaseUrl } from '@/lib/urls';
32	
33	export interface Props {
34	    name: string;
35	    email: string;
36	    token: string;
37	}
38	
39	const ClaimSignupSchema = z
40	    .object({
41	        password: z
42	            .string()
43	            .min(8, { message: 'Password must be at least 8 characters long' }),
44	        confirmPassword: z
45	            .string()
46	            .min(1, { message: 'Please confirm your password' }),
47	    })
48	    .refine((data) => data.password === data.confirmPassword, {
49	        message: 'Passwords do not match',
50	        path: ['confirmPassword'],
51	    });
52	
53	export const ClaimSignup = ({ name, email, token }: Props) => {
54	    const [loading, setLoading] = useState(false);
55	    const [signupError, setSignupError] = useState<string | undefined>(
56	        undefined,
57	    );
58	    const router = useRouter();
59	    const redirectPath = `/footy/auth/claim/${encodeURIComponent(token)}/finish`;
60	    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();
61	
62	    const form = useForm({
63	        initialValues: {
64	            password: '',
65	            confirmPassword: '',
66	        },
67	        validate: zod4Resolver(ClaimSignupSchema),
68	        validateInputOnBlur: true,
69	    });
70	
71	    const handleSignUp = async (values: z.infer<typeof ClaimSignupSchema>) => {
72	        setLoading(true);
73	        setSignupError(undefined);
74	
75	        try {
76	            await authClient.signUp.email(
77	                {
78	                    name: name,
79	                    email: email,
80	                    password: values.password,
81	                },
82	                {
83	                    onError: (ctx) => {
84	                        alert(ctx.error.message);
85	                    },
86	                },
87	            );
88	
89	            router.push(redirectPath);
90	        } catch (err) {
91	            captureUnexpectedError(err, {
92	                layer: 'client',
93	                action: 'signUpWithEmail',
94	                component: 'ClaimSignup',
95	                route: '/claim-signup',
96	                extra: {
97	                    redirectPath,
98	                },
99	            });
100	            setSignupError('Something went wrong. Please try again.');
101	        } finally {
102	            setLoading(false);
103	        }
104	    };
105	
106	    const errorNotification = signupError ? (
107	        <Notification
108	            icon={<IconX size={config.notificationIconSize} />}
109	            color="red"
110	            onClose={() => setSignupError(undefined)}
111	        >
112	            {signupError}
113	        </Notification>
114	    ) : null;
115	
116	    return (
117	        <Paper
118	            w="100%"
119	            maw="35rem"
120	            mx="auto"
121	            mt="xl"
122	        >
123	            <Stack mb="lg">
124	                <Title
125	                    order={2}
126	                    mb="xs"
127	                    w="100%"
128	                    ta="center"
129	                >
130	                    Finish creating your login
131	                </Title>
132	                <Text ta="center">
133	                    Your email address &quot;{email}&quot; has been verified.
134	                    Choose how you want to sign in.
135	                </Text>
136	                <Divider mb="xs" />
137	                <Group
138	                    justify="center"
139	                    w="100%"
140	                    mb="md"
141	                >
142	                    <UnstyledButton
143	                        onClick={() => signInWithGoogle(socialRedirect)}
144	                        w="fit-content"
145	                        type="button"
146	                    >
147	                        <Image
148	                            src="/google-signin-button-light.svg"
149	                            alt="Sign in with Google"
150	                            w={180}
151	                            h={40}
152	                        />
153	                    </UnstyledButton>
154	                    <UnstyledButton
155	                        onClick={() => signInWithMicrosoft(socialRedirect)}
156	                        w="fit-content"
157	                        type="button"
158	                    >
159	                        <Image
160	                            src="/microsoft-signin-button-light.svg"
161	                            alt="Sign in with Microsoft"
162	                            w={215}
163	                            h={41}
164	                        />
165	                    </UnstyledButton>
166	                </Group>
167	                <Divider
168	                    label="or"
169	                    labelPosition="center"
170	                />
171	            </Stack>
172	
173	            <Box
174	                component="form"
175	                onSubmit={form.onSubmit(handleSignUp)}
176	            >
177	                <Stack>
178	                    <PasswordFields
179	                        passwordProps={form.getInputProps('password')}
180	                        confirmPasswordProps={form.getInputProps(
181	                            'confirmPassword',
182	                        )}
183	                    />
184	                    {errorNotification}
185	                    <Button
186	                        type="submit"
187	                        fullWidth
188	                        loading={loading}
189	                        disabled={!form.isValid()}
190	                    >
191	                        Create login
192	                    </Button>
193	                </Stack>
194	            </Box>
195	        </Paper>
196	    );
197	};
