39	export const SignIn = ({ admin, redirect }: Props) => {
40	    const [loading, setLoading] = useState(false);
41	    const [loginError, setLoginError] = useState<boolean>(false);
42	    const router = useRouter();
43	    const pathname = usePathname();
44	    const redirectPath = redirect ?? pathname;
45	    const socialRedirect = new URL(redirectPath, getPublicBaseUrl()).toString();
46	    const form = useForm({
47	        initialValues: {
48	            email: '',
49	            password: '',
50	        },
51	
52	        validateInputOnBlur: true,
53	
54	        validate: {
55	            email: (value) =>
56	                /^\S+@\S+\.\S+$/.test(value) ? null : 'Invalid email format',
57	            password: (value) =>
58	                value.length >= 8
59	                    ? null
60	                    : 'Password must be at least 8 characters long',
61	        },
62	    });
63	
64	    const handleSignIn = async (values: {
65	        email: string;
66	        password: string;
67	    }) => {
68	        setLoading(true);
69	        setLoginError(false);
70	
71	        try {
72	            await authClient.signIn.email({
73	                email: values.email,
74	                password: values.password,
75	            });
76	            router.push(redirectPath);
77	        } catch (error) {
78	            captureUnexpectedError(error, {
79	                layer: 'client',
80	                action: 'signInWithEmail',
81	                component: 'SignIn',
82	                route: pathname,
83	                extra: {
84	                    redirectPath,
85	                },
86	            });
87	            setLoginError(true);
88	        } finally {
89	            setLoading(false);
90	        }
91	    };
92	
93	    if (loading) {
94	        return (
95	            <Center>
96	                <Loader />
97	            </Center>
98	        );
99	    }
100	
101	    let title = 'Sign in to your account';
102	
103	    if (admin === true) {
104	        title = 'You must be logged in as an administrator to use this page.';
105	    } else if (admin === false) {
106	        title = 'You must be logged in to use this page.';
107	    }
108	
109	    const errorNotification = loginError ? (
110	        <Notification
111	            icon={<IconX size={config.notificationIconSize} />}
112	            color="red"
113	            onClose={() => setLoginError(false)}
114	        >
115	            Login failed. Please check your details and try again.
116	        </Notification>
117	    ) : null;
118	
119	    return (
120	        <Paper
121	            w="100%"
122	            maw="35rem"
123	            mx="auto"
124	            mt="xl"
125	        >
126	            <Stack mb="lg">
127	                <Title
128	                    order={2}
129	                    mb="xs"
130	                    w="100%"
131	                    ta="center"
132	                >
133	                    {title}
134	                </Title>
135	                <Divider mb="xs" />
136	                <Group
137	                    justify="center"
138	                    w="100%"
139	                    mb="md"
140	                >
141	                    <UnstyledButton
142	                        onClick={() => signInWithGoogle(socialRedirect)}
143	                        w="fit-content"
144	                    >
145	                        <Image
146	                            src="/google-signin-button-light.svg"
147	                            alt="Sign in with Google"
148	                            w={180}
149	                            h={40}
150	                        />
151	                    </UnstyledButton>
152	                    <UnstyledButton
153	                        onClick={() => signInWithMicrosoft(socialRedirect)}
154	                        w="fit-content"
155	                    >
156	                        <Image
157	                            src="/microsoft-signin-button-light.svg"
158	                            alt="Sign in with Microsoft"
159	                            w={215}
160	                            h={41}
161	                        />
162	                    </UnstyledButton>
163	                </Group>
164	                <Divider
165	                    label="or"
166	                    labelPosition="center"
167	                />
168	            </Stack>
169	
170	            <Box
171	                component="form"
172	                onSubmit={form.onSubmit(handleSignIn)}
173	            >
174	                <Stack>
175	                    <TextInput
176	                        withAsterisk
177	                        label="Email"
178	                        placeholder="Enter your email"
179	                        rightSection={<IconAt size={16} />}
180	                        {...form.getInputProps('email')}
181	                        value={form.values.email}
182	                    />
183	                    <PasswordInput
184	                        withAsterisk
185	                        label="Password"
186	                        placeholder="Enter your password"
187	                        rightSection={<IconLock size={16} />}
188	                        {...form.getInputProps('password')}
189	                        value={form.values.password}
190	                    />
191	                    {errorNotification}
192	                    <Group mt="sm">
193	                        <Anchor
194	                            href="/footy/forgottenpassword"
195	                            size="sm"
196	                        >
197	                            Forgot your password ?
198	                        </Anchor>
199	                    </Group>
200	                    <Button
201	                        type="submit"
202	                        fullWidth
203	                        loading={loading}
204	                        disabled={!form.isValid()}
205	                    >
206	                        Sign In
207	                    </Button>
208	                </Stack>
209	            </Box>
210	        </Paper>
211	    );
212	};
