1	'use client';
2	
3	import { Box, Button, Flex, Paper, Select } from '@mantine/core';
4	import { useForm } from '@mantine/form';
5	import { useDisclosure } from '@mantine/hooks';
6	import { notifications } from '@mantine/notifications';
7	import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
8	import { useRouter } from 'next/navigation';
9	
10	import { config } from '@/lib/config';
11	import type {
12	    SetGameResultProxy,
13	    SetGameWinner,
14	} from '@/types/actions/SetGameResult';
15	
16	export interface GameResultFormProps {
17	    gameDayId: number;
18	    bibs: 'A' | 'B' | null;
19	    winners: SetGameWinner;
20	    setGameResult: SetGameResultProxy;
21	}
22	
23	export const GameResultForm = ({
24	    gameDayId,
25	    bibs,
26	    winners,
27	    setGameResult,
28	}: GameResultFormProps) => {
29	    const router = useRouter();
30	    const [isSaving, { open: setSaving, close: setSaved }] =
31	        useDisclosure(false);
32	    const form = useForm<{
33	        bibs: 'A' | 'B' | 'none';
34	        winner: 'A' | 'B' | 'draw' | 'none';
35	    }>({
36	        initialValues: {
37	            bibs: bibs ?? 'none',
38	            winner: winners ?? 'none',
39	        },
40	    });
41	
42	    const handleSave = async (values: {
43	        bibs: 'A' | 'B' | 'none';
44	        winner: 'A' | 'B' | 'draw' | 'none';
45	    }) => {
46	        const notificationId = 'game-result-update';
47	        notifications.show({
48	            id: notificationId,
49	            loading: true,
50	            title: 'Updating game details',
51	            message: 'Saving bibs and result...',
52	            autoClose: false,
53	            withCloseButton: false,
54	        });
55	
56	        setSaving();
57	        try {
58	            await setGameResult({
59	                gameDayId,
60	                bibs: values.bibs === 'none' ? null : values.bibs,
61	                winner: values.winner === 'none' ? null : values.winner,
62	            });
63	
64	            notifications.update({
65	                id: notificationId,
66	                color: 'teal',
67	                title: 'Game updated',
68	                message: 'Bibs and result were updated.',
69	                icon: <IconCheck size={config.notificationIconSize} />,
70	                loading: false,
71	                autoClose: config.notificationAutoClose,
72	            });
73	
74	            form.resetDirty(values);
75	            router.refresh();
76	        } catch (err) {
77	            const errorMessage =
78	                err instanceof Error ? err.message : 'Failed to update game';
79	            notifications.update({
80	                id: notificationId,
81	                color: 'red',
82	                title: 'Error',
83	                message: errorMessage,
84	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
85	                loading: false,
86	                autoClose: false,
87	                withCloseButton: true,
88	            });
89	        } finally {
90	            setSaved();
91	        }
92	    };
93	
94	    return (
95	        <Box
96	            component="form"
97	            onSubmit={form.onSubmit(handleSave)}
98	        >
99	            <Paper
100	                p="md"
101	                radius="md"
102	            >
103	                <Flex
104	                    gap="sm"
105	                    direction={{ base: 'column', sm: 'row' }}
106	                    align={{ base: 'stretch', sm: 'flex-end' }}
107	                >
108	                    <Select
109	                        label="Bibs"
110	                        data={[
111	                            { value: 'none', label: 'Not set' },
112	                            { value: 'A', label: 'Team A' },
113	                            { value: 'B', label: 'Team B' },
114	                        ]}
115	                        value={form.values.bibs}
116	                        /* v8 ignore next -- allowDeselect={false} means value is never null */
117	                        onChange={(value) =>
118	                            form.setFieldValue('bibs', value ?? 'none')
119	                        }
120	                        allowDeselect={false}
121	                        miw="8rem"
122	                        w={{ base: '100%', sm: 'auto' }}
123	                    />
124	                    <Select
125	                        label="Result"
126	                        data={[
127	                            { value: 'none', label: 'Not set' },
128	                            { value: 'A', label: 'A won' },
129	                            { value: 'draw', label: 'Draw' },
130	                            { value: 'B', label: 'B won' },
131	                        ]}
132	                        value={form.values.winner}
133	                        /* v8 ignore next -- allowDeselect={false} means value is never null */
134	                        onChange={(value) =>
135	                            form.setFieldValue('winner', value ?? 'none')
136	                        }
137	                        allowDeselect={false}
138	                        miw="8rem"
139	                        w={{ base: '100%', sm: 'auto' }}
140	                    />
141	                    <Button
142	                        type="submit"
143	                        loading={isSaving}
144	                        disabled={!form.isDirty()}
145	                        w={{ base: '100%', sm: 'auto' }}
146	                    >
147	                        Save
148	                    </Button>
149	                </Flex>
150	            </Paper>
151	        </Box>
152	    );
153	};
