229	                                        <Text size="sm">
230	                                            {formatCurrency(debt.amount)}
231	                                        </Text>
232	                                    </Group>
233	                                }
234	                            />
235	                        ))}
236	                    </Stack>
237	                )}
238	
239	                <Group
240	                    wrap="nowrap"
241	                    justify="flex-end"
242	                >
243	                    <Text
244	                        size="sm"
245	                        fw={500}
246	                    >
247	                        {formatCurrency(totalAmount)}
248	                    </Text>
249	                    <Button
250	                        type="submit"
251	                        disabled={
252	                            form.values.checkedIds.length === 0 ||
253	                            submittingPlayerId === row.player.id
254	                        }
255	                        loading={submittingPlayerId === row.player.id}
256	                    >
257	                        Paid
258	                    </Button>
259	                </Group>
260	            </Stack>
261	        </Box>
262	    );
263	};
