3	import {
4	    Anchor,
5	    Box,
6	    Group,
7	    Image,
8	    Popover,
9	    ScrollAreaAutosize,
10	    Stack,
11	    Text,
12	} from '@mantine/core';
13	import { json } from 'd3-fetch';
14	import { geoMercator, geoPath } from 'd3-geo';
15	import { select } from 'd3-selection';
16	import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
17	import * as topojson from 'topojson-client';
18	import type { GeometryCollection, Topology } from 'topojson-specification';
19	
20	import { CountrySupporterWithPlayerDataType } from '@/types';
21	
22	/**
23	 * Mapping from database country names to their corresponding TopoJSON atlas
24	 * names where they differ. Multiple DB names may map to the same atlas entry
25	 * (e.g. the four UK home nations all map to "United Kingdom").
26	 */
27	const COUNTRY_NAME_MAP: Record<string, string> = {
28	    England: 'United Kingdom',
29	    'Northern Ireland': 'United Kingdom',
30	    Scotland: 'United Kingdom',
31	    Wales: 'United Kingdom',
32	    'Russian Federation': 'Russia',
33	    'Bosnia and Herzegovina': 'Bosnia and Herz.',
34	    'Central African Republic': 'Central African Rep.',
35	    'Dominican Republic': 'Dominican Rep.',
36	    'Equatorial Guinea': 'Eq. Guinea',
37	    Swaziland: 'eSwatini',
38	    'United States': 'United States of America',
39	};
40	
41	/**
42	 * Properties for the {@link PlayerCountryMap} component.
43	 */
44	export interface Props {
45	    /** Array of country supporter entries with player data for highlighting and hover. */
46	    countries: CountrySupporterWithPlayerDataType[];
47	    /**
48	     * Width of the SVG viewport in pixels. When omitted, the map measures
49	     * its container and fills it, staying responsive to viewport/zoom
50	     * changes; passing an explicit value (e.g. in Storybook) fixes the size
51	     * instead.
52	     */
53	    width?: number;
54	    /**
55	     * Height of the SVG viewport in pixels. When omitted, it is derived from
56	     * the (possibly measured) width using the default map's aspect ratio.
57	     */
58	    height?: number;
59	}
60	
61	/** Shape of properties on each country feature in the TopoJSON atlas. */
62	interface CountryProperties {
63	    name: string;
64	}
65	
66	/** Fill colour applied to highlighted (supported) countries. */
67	const HIGHLIGHT_FILL = '#228be6';
68	/** Fill colour for countries that are not highlighted. */
69	const DEFAULT_FILL = '#ccc';
70	/** Stroke colour for country borders. */
71	const STROKE_COLOUR = '#fff';
72	/** Stroke width for country borders. */
73	const STROKE_WIDTH = 0.5;
74	/** Maximum height of the scrollable player list inside the hover popover. */
75	const POPOVER_MAX_HEIGHT = 200;
76	/** Size of mugshot thumbnails in the hover popover. */
77	const MUGSHOT_SIZE = 32;
78	/** Delay in ms before closing the popover after mouse leaves a country path. */
79	const CLOSE_DELAY_MS = 200;
80	/** Default SVG width in pixels, used until the container has been measured. */
81	const DEFAULT_WIDTH = 960;
82	/** Default SVG height in pixels, used to derive the map's aspect ratio. */
83	const DEFAULT_HEIGHT = 500;
84	
85	/**
86	 * Resolves a database country name to its TopoJSON atlas equivalent.
87	 * Returns the mapped name if one exists, or the original name otherwise.
88	 */
89	const toAtlasName = (dbName: string): string =>
90	    COUNTRY_NAME_MAP[dbName] ?? dbName;
91	
92	/**
93	 * A D3-powered world map that highlights countries supported by players and
94	 * shows player mugshots in a popover on hover.
95	 *
96	 * Renders all countries from a TopoJSON world atlas and fills those whose
97	 * names match the supplied supporter entries with an accent colour. When a
98	 * highlighted country is hovered, a popover displays the mugshot and name of
99	 * each supporting player, grouped by their database country name (useful
100	 * when multiple nations share one atlas polygon, e.g. the four UK home
101	 * nations). For countries with many supporters the list is scrollable.
102	 *
103	 * Based on the approach described at
104	 * {@link http://www.d3noob.org/2013/03/a-simple-d3js-map-explained.html}.
105	 */
106	export const PlayerCountryMap = ({
107	    countries,
108	    width: widthProp,
109	    height: heightProp,
110	}: Props) => {
111	    const wrapperRef = useRef<HTMLDivElement>(null);
112	    const svgRef = useRef<SVGSVGElement>(null);
113	    const [measuredWidth, setMeasuredWidth] = useState(DEFAULT_WIDTH);
114	    const width = widthProp ?? measuredWidth;
115	    const height =
116	        heightProp ?? Math.round((width * DEFAULT_HEIGHT) / DEFAULT_WIDTH);
117	    /** Projected centroids for each highlighted atlas country. */
118	    const centroidsRef = useRef<Map<string, { x: number; y: number }>>(
119	        new Map(),
120	    );
121	    /** Timer handle for the delayed popover close. */
122	    const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
123	    /** Whether the mouse is currently inside the popover dropdown. */
124	    const dropdownHoveredRef = useRef(false);
125	    const [popoverOpen, setPopoverOpen] = useState(false);
126	    const [popoverPos, setPopoverPos] = useState<{ x: number; y: number }>({
127	        x: 0,
128	        y: 0,
129	    });
130	    const [hoveredCountry, setHoveredCountry] = useState<string | null>(null);
131	
132	    /**
133	     * Builds a lookup from lower-cased atlas country name to an array of
134	     * supporters. Multiple DB country names that share the same atlas name
135	     * are grouped together.
136	     */
137	    const supportersByAtlasName = useMemo(() => {
138	        const map = new Map<string, CountrySupporterWithPlayerDataType[]>();
139	        for (const cs of countries) {
140	            const key = toAtlasName(cs.country.name).toLowerCase();
141	            const arr = map.get(key) ?? [];
142	            arr.push(cs);
143	            map.set(key, arr);
144	        }
145	        return map;
146	    }, [countries]);
147	
148	    /**
149	     * Returns the supporters for the currently hovered country, grouped by
150	     * their original database country name for display purposes.
151	     */
152	    const hoveredGroups = useMemo(() => {
153	        if (!hoveredCountry) return [];
154	        /* v8 ignore next -- only countries in supportersByAtlasName trigger hover; get() always returns an array */
155	        const supporters = supportersByAtlasName.get(hoveredCountry) ?? [];
156	        const grouped = new Map<string, CountrySupporterWithPlayerDataType[]>();
157	        for (const s of supporters) {
158	            const key = s.country.name;
159	            const arr = grouped.get(key) ?? [];
160	            arr.push(s);
161	            grouped.set(key, arr);
162	        }
163	        return Array.from(grouped.entries());
164	    }, [hoveredCountry, supportersByAtlasName]);
165	
166	    /** Cancels any pending delayed close. */
167	    const cancelClose = useCallback(() => {
168	        if (closeTimerRef.current) {
169	            clearTimeout(closeTimerRef.current);
170	            closeTimerRef.current = null;
171	        }
172	    }, []);
173	
174	    /** Schedules a delayed popover close unless the dropdown is hovered. */
175	    const scheduleClose = useCallback(() => {
176	        cancelClose();
177	        closeTimerRef.current = setTimeout(() => {
178	            /* c8 ignore next — onMouseEnter always cancels the timer before setting dropdownHoveredRef; the timer can only fire while the flag is false */
179	            if (!dropdownHoveredRef.current) {
180	                setPopoverOpen(false);
181	                setHoveredCountry(null);
182	            }
183	        }, CLOSE_DELAY_MS);
184	    }, [cancelClose]);
185	
186	    /**
187	     * Handles mouse-enter on a highlighted country path. Anchors the popover
188	     * to the country's projected centroid for a stable position.
189	     */
190	    const handleMouseEnter = useCallback(
191	        (atlasName: string) => {
192	            cancelClose();
193	            const lowerName = atlasName.toLowerCase();
194	            const centroid = centroidsRef.current.get(lowerName);
195	            /* v8 ignore next -- centroid is always pre-computed before a D3 mouseenter can fire */
196	            if (centroid) {
197	                setPopoverPos(centroid);
198	            }
199	            setHoveredCountry(lowerName);
200	            setPopoverOpen(true);
201	        },
202	        [cancelClose],
203	    );
204	
205	    /** Handles mouse-leave on a highlighted country path. */
206	    const handleMouseLeave = useCallback(() => {
207	        scheduleClose();
208	    }, [scheduleClose]);
209	
210	    /* Keeps the map sized to its container so it stays responsive to
211	       viewport/zoom changes instead of overflowing at a fixed pixel width.
212	       Skipped when the caller pins an explicit width (e.g. Storybook). */
213	    useEffect(() => {
214	        if (widthProp !== undefined) return undefined;
215	        const el = wrapperRef.current;
216	        /* c8 ignore next -- wrapperRef is always attached before effects run; the null path is a defensive guard only */
217	        if (!el) return undefined;
218	
219	        const observer = new ResizeObserver((entries) => {
220	            if (entries.length === 0) return;
221	            const measured = entries[0].contentRect.width;
222	            if (measured > 0) setMeasuredWidth(measured);
223	        });
224	        observer.observe(el);
225	        return () => observer.disconnect();
226	    }, [widthProp]);
227	
228	    useEffect(() => {
229	        /* c8 ignore next — svgRef is always attached before effects run; the null path is a defensive guard only */
230	        if (!svgRef.current) return;
231	
232	        const svg = select(svgRef.current);
233	        svg.selectAll('*').remove();
234	
235	        const projection = geoMercator()
236	            .center([0, 20])
237	            .scale(width / 6.5)
238	            .translate([width / 2, height / 2]);
239	
240	        const path = geoPath().projection(projection);
241	
242	        const g = svg.append('g');
243	
244	        const supportedNames = new Set(supportersByAtlasName.keys());
245	
246	        void json<Topology>('/countries-110m.json').then((topology) => {
247	            if (!topology) return undefined;
248	
249	            const geojson = topojson.feature(
250	                topology,
251	                topology.objects.countries as GeometryCollection,
252	            );
253	
254	            type CountryFeature = GeoJSON.Feature<
255	                GeoJSON.Geometry,
256	                CountryProperties
257	            >;
258	            const features = geojson.features as CountryFeature[];
259	
260	            /* Pre-compute projected centroids for highlighted countries so
261	               the popover can be anchored to a stable position. */
262	            const newCentroids = new Map<string, { x: number; y: number }>();
263	            for (const f of features) {
264	                const name = (f.properties?.name ?? '').toLowerCase();
265	                if (supportedNames.has(name)) {
266	                    const [cx, cy] = path.centroid(f);
267	                    newCentroids.set(name, { x: cx, y: cy });
268	                }
269	            }
270	            centroidsRef.current = newCentroids;
271	
272	            g.selectAll<SVGPathElement, CountryFeature>('path')
273	                .data(features)
274	                .enter()
275	                .append('path')
276	                .attr('d', path)
277	                .attr('fill', (d) => {
278	                    const name = (d.properties?.name ?? '').toLowerCase();
279	                    return supportedNames.has(name)
280	                        ? HIGHLIGHT_FILL
281	                        : DEFAULT_FILL;
282	                })
283	                .attr('stroke', STROKE_COLOUR)
284	                .attr('stroke-width', STROKE_WIDTH)
285	                .on('mouseenter', function (_event: MouseEvent, d) {
286	                    const name = (d.properties?.name ?? '').toLowerCase();
287	                    if (supportedNames.has(name)) {
288	                        handleMouseEnter(name);
289	                    }
290	                })
291	                .on('mouseleave', function () {
292	                    handleMouseLeave();
293	                });
294	
295	            return undefined;
296	        });
297	    }, [
298	        countries,
299	        width,
300	        height,
301	        supportersByAtlasName,
302	        handleMouseEnter,
303	        handleMouseLeave,
304	    ]);
305	
306	    return (
307	        <Box
308	            ref={wrapperRef}
309	            pos="relative"
310	            w="100%"
311	            data-testid="player-country-map"
312	        >
313	            <svg
314	                ref={svgRef}
315	                width={width}
316	                height={height}
317	            />
318	            <Popover
319	                opened={popoverOpen}
320	                position="bottom"
321	                withArrow
322	                shadow="md"
323	                withinPortal={false}
324	            >
325	                <Popover.Target>
326	                    <Box
327	                        pos="absolute"
328	                        left={popoverPos.x}
329	                        top={popoverPos.y}
330	                        w={1}
331	                        h={1}
332	                        pe="none"
333	                    />
334	                </Popover.Target>
335	                <Popover.Dropdown
336	                    data-testid="country-popover-dropdown"
337	                    onMouseEnter={() => {
338	                        dropdownHoveredRef.current = true;
339	                        cancelClose();
340	                    }}
341	                    onMouseLeave={() => {
342	                        dropdownHoveredRef.current = false;
343	                        scheduleClose();
344	                    }}
345	                    pe="auto"
346	                >
347	                    <ScrollAreaAutosize mah={POPOVER_MAX_HEIGHT}>
348	                        <Stack gap="xs">
349	                            {hoveredGroups.map(([countryName, supporters]) => (
350	                                <Stack
351	                                    key={countryName}
352	                                    gap={4}
353	                                >
354	                                    <Text
355	                                        size="xs"
356	                                        fw={700}
357	                                    >
358	                                        {countryName}
359	                                    </Text>
360	                                    {supporters.map((s) => (
361	                                        <Anchor
362	                                            key={s.playerId}
363	                                            href={`/footy/player/${s.playerId}`}
364	                                            underline="never"
365	                                        >
366	                                            <Group
367	                                                gap="xs"
368	                                                wrap="nowrap"
369	                                            >
370	                                                <Image
371	                                                    src={`/api/footy/player/${s.playerId}/mugshot`}
372	                                                    alt={
373	                                                        s.player.name ??
374	                                                        `Player ${s.playerId}`
375	                                                    }
376	                                                    w={MUGSHOT_SIZE}
377	                                                    h={MUGSHOT_SIZE}
378	                                                    radius="xl"
379	                                                />
380	                                                <Text size="sm">
381	                                                    {s.player.name ??
382	                                                        `Player ${s.playerId}`}
383	                                                </Text>
384	                                            </Group>
385	                                        </Anchor>
386	                                    ))}
387	                                </Stack>
388	                            ))}
389	                        </Stack>
390	                    </ScrollAreaAutosize>
391	                </Popover.Dropdown>
392	            </Popover>
393	        </Box>
394	    );
395	};
